const fmt = (n: number) => '$' + Math.round(n).toLocaleString('es-CO')

function evaluarComision(formula: string, total: number, porcentaje: number): number {
  try {
    // porcentaje llega como número entero (ej. 5 = 5%) — se normaliza a fracción
    // (5/100=0.05) ANTES de pasarlo a la fórmula, para que cualquier fórmula
    // escrita en texto (total*porcentaje, total/1.19*porcentaje, etc.) sea
    // matemáticamente correcta sin que el usuario tenga que escribir /100.
    const r = new Parser().parse(formula || 'total/1.19*porcentaje').evaluate({ total, porcentaje: porcentaje / 100 })
    return Number.isFinite(r) ? Math.round(r) : 0
  } catch {
    return 0
  }
}
const fmtShort = (n: number): string => {
  if (n >= 1_000_000) return '$' + (n / 1_000_000).toLocaleString('es-CO', { minimumFractionDigits: 0, maximumFractionDigits: 2 }) + ' mill'
  if (n >= 1_000)     return '$' + (n / 1_000).toLocaleString('es-CO',     { minimumFractionDigits: 0, maximumFractionDigits: 1 }) + ' K'
  return '$' + Math.round(n).toLocaleString('es-CO')
}

type LineaPago = { id: string; metodoPago: 'efectivo' | 'transferencia'; monto: string; voucherKey: string | null; voucherDatosIA: any; cargandoVoucher: boolean }
function crearLinea(): LineaPago { return { id: crypto.randomUUID(), metodoPago: 'efectivo', monto: '', voucherKey: null, voucherDatosIA: null, cargandoVoucher: false } }

