  useEffect(() => {
    fetch('/api/integracion/estado').then(r => r.json()).then(d => {
      setSyncInfo({ ultimaSync: d.ultimaSync ?? null, ultimaSyncCompleta: d.ultimaSyncCompleta ?? null, tieneIntegracion: d.tieneIntegracion ?? false, historial: d.historial ?? [] })
    }).catch(() => {})
  }, [])

  async function sincronizar() {
    setSincronizando(true)
    try {
      await fetch('/api/integracion/sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tipo: 'delta' })
      })
    } catch {}
    await cargarDatos(buscar)
    fetch('/api/integracion/estado').then(r => r.json()).then(d => setSyncInfo({ ultimaSync: d.ultimaSync ?? null, ultimaSyncCompleta: d.ultimaSyncCompleta ?? null, tieneIntegracion: d.tieneIntegracion ?? false, historial: d.historial ?? [] })).catch(() => {})
    setSincronizando(false)
  }

  // Agregados por estado
  const porEstado = carteras.reduce((acc, c) => {
    const detalles = c.DetalleCartera || []
    for (const d of detalles) {
      const vf = Number(d.valorFactura ?? d.valor)
      const ab = Number(d.abonos ?? 0)
      const saldo = Math.max(0, vf - ab)
      const { estado } = calcularEstado(saldo, vf, ab, d.fechaVencimiento ? new Date(d.fechaVencimiento) : null)
      acc[estado] = (acc[estado] ?? 0) + saldo
    }
    return acc
  }, {} as Record<string, number>)

  // Edades de cartera — desde API (todas las deudas, no solo la página)
  const EDADES = ['0-30','31-60','61-90','91-120','+120'] as const
  type Edad = typeof EDADES[number]
  const porEdad = porEdadApi as Record<Edad, number>

  // Admin: por vendedor — desde API
  // Filtrar 'Sin vendedor' — deudas de apiIds sin Empleado en BD
  const porEdadVendedor = Object.fromEntries(
    Object.entries(porEdadVendedorApi as Record<string, Record<Edad, number>>)
      .filter(([nombre]) => nombre !== 'Sin vendedor')
  ) as Record<string, Record<Edad, number>>

  const totalPendiente = totalReal ? totalReal.saldoPendiente : carteras.reduce((s, c) => s + Number(c.saldoPendiente), 0)

  // ── CPC resize ──────────────────────────────────────────────────
  const CPC_COLS_BASE = [220, 160, 120, 120, 130, 110, 160] // cliente,vendedor,factura,vcto,saldo,estado,acciones
  const CPC_STORAGE = 'dt-widths-cpc'
  const [cpcWidths, setCpcWidths] = useState<number[]>(() => {
    if (typeof window !== 'undefined') {
      try {
        const s = localStorage.getItem(CPC_STORAGE)
        if (s) { const p = JSON.parse(s); if (Array.isArray(p)) return p }
      } catch {}
    }
    return CPC_COLS_BASE
  })
  useEffect(() => {
    try { localStorage.setItem(CPC_STORAGE, JSON.stringify(cpcWidths)) } catch {}
  }, [cpcWidths])

  // Cerrar picker día al hacer click fuera
  useEffect(() => {
    if (!pickerDiaAbierto) return
    const handler = (e: MouseEvent) => {
      const t = e.target as HTMLElement
      if (!t.closest('[data-picker-dia]')) setPickerDiaAbierto(false)
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [pickerDiaAbierto])
  const cpcResizing = useRef<{ci:number;sx:number;sw:number}|null>(null)
  const onCpcResize = useCallback((e: React.MouseEvent, ci: number) => {
    e.preventDefault(); e.stopPropagation()
    cpcResizing.current = { ci, sx: e.clientX, sw: cpcWidths[ci] }
    const onMove = (ev: MouseEvent) => {
      if (!cpcResizing.current) return
      const { ci, sx, sw } = cpcResizing.current
      setCpcWidths(prev => { const w=[...prev]; w[ci]=Math.max(60,sw+ev.clientX-sx); return w })
    }
    const onUp = () => { cpcResizing.current=null; window.removeEventListener('mousemove',onMove); window.removeEventListener('mouseup',onUp) }
    window.addEventListener('mousemove',onMove); window.addEventListener('mouseup',onUp)
  }, [cpcWidths])

  const filtradas = carteras

  // --- Importar ---


  // --- Sync UpTres individual ---
  async function syncCliente(cartera: any) {
    const clienteApiId = cartera?.cliente?.apiId || cartera?.clienteApiId
    if (!clienteApiId) return
    try {
      await fetch('/api/integracion/sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tipo: 'cliente', clienteApiId })
      })
      await cargarDatos()
    } catch {}
  }

  // --- Recaudar ---
  async function abrirRecaudar(cartera: any) {
    setRecaudandoCartera(cartera)
    setDetalleData(null)
    setFacturasSeleccionadas([])
    setLineasPago([crearLinea()])
    setLoadingDetalle(true)
    const controller = new AbortController()
    const timer = setTimeout(() => controller.abort(), 12000)
    let data: any = {}
    try {
      const res = await fetch(`/api/cartera/${cartera.clienteId}`, { signal: controller.signal })
      data = await res.json()
      if (!res.ok) throw new Error(data.error || `Error ${res.status}`)
    } catch (e: any) {
      clearTimeout(timer)
      setLoadingDetalle(false)
      const msg = e?.name === 'AbortError' ? 'Tiempo de espera agotado. Intenta de nuevo.' : 'No se pudo cargar la deuda. Intenta de nuevo.'
      alert(msg)
      setRecaudandoCartera(null)
      return
    } finally {
      clearTimeout(timer)
      setLoadingDetalle(false)
    }
    const dc = data.cartera
    if (!dc) { setDetalleData(null); return }
    dc.DetalleCartera = (dc.deudas || []).map((d: any) => ({
      id: d.id,
      syncDeudaId: d.id,
      valorFactura: d.valor,
      abonos: d.valor - d.saldoReal,
      saldoPendiente: d.saldoReal,
      ...(() => {
        const saldo = Math.max(0, d.saldoReal)
        const vf = Number(d.valor || 0)
        const ab = vf - saldo
        const fv = d.fechaVencimiento ? new Date(d.fechaVencimiento) : null
        const { estado, label, color } = calcularEstado(saldo, vf, ab, fv)
        return { estado, estadoLabel: label, estadoColor: color }
      })(),
      numeroFactura: d.numeroFactura || d.numeroOrden,
      fechaVencimiento: d.fechaVencimiento,
      concepto: null,
      _sync: true,
    }))
    setDetalleData(dc)
    const pendientes = (dc.DetalleCartera || [])
      .filter((d: any) => d.estado !== 'pagada')
      .sort((a: any, b: any) => { const fa = a.fechaVencimiento ? new Date(a.fechaVencimiento).getTime() : Infinity; const fb = b.fechaVencimiento ? new Date(b.fechaVencimiento).getTime() : Infinity; return fa - fb })
    setFacturasSeleccionadas(pendientes[0]?.id ? [pendientes[0].id] : [])
    // No resetear lineasPago si ya tiene voucher, está cargando, o tiene múltiples líneas
    setLineasPago(prev => {
      const activa = prev.some(l => l.voucherKey || l.voucherDatosIA || l.cargandoVoucher || l.monto)
      if (activa || prev.length > 1) return prev
      return [crearLinea()]
    })
  }

